1	// Package batchreg registers supply-chain batches in a local JSON file.
2	//
3	// The registry file format is public and stable:
4	//
5	//	{
6	//	  "version": 1,
7	//	  "batches": [
8	//	    {"batch": "B-001", "product": "P-7", "quantity": 120, "unit": "kg"}
9	//	  ]
10	//	}
11	//
12	// Batch ids are unique per file (compared byte for byte, so casing and
13	// interior characters matter). Re-registering an existing id with the same
14	// product, quantity and unit is an idempotent duplicate confirmation; any
15	// differing field is rejected without touching stored records.
16	package batchreg
17	
18	import (
19		"bytes"
20		"encoding/json"
21		"errors"
22		"fmt"
23		"io"
24		"io/fs"
25		"os"
26		"path/filepath"
27		"regexp"
28		"strconv"
29		"strings"
30	)
31	
32	// FormatVersion is the only registry file format understood by this build.
33	const FormatVersion = 1
34	
35	// MaxQuantity is the inclusive upper bound for a batch quantity.
36	const MaxQuantity = int64(1<<63 - 1)
37	
38	var quantityPattern = regexp.MustCompile(`^[0-9]+$`)
39	
40	// Batch is the four-piece record of one supply-chain batch.
41	type Batch struct {
42		Batch    string `json:"batch"`
43		Product  string `json:"product"`
44		Quantity int64  `json:"quantity"`
45		Unit     string `json:"unit"`
46	}
47	
48	// Registry is the on-disk registry file.
49	type Registry struct {
50		Version int     `json:"version"`
51		Batches []Batch `json:"batches"`
52	}
53	
54	// Input is a normalized registration request.
55	type Input struct {
56		Batch    string
57		Product  string
58		Quantity int64
59		Unit     string
60	}
61	
62	// Outcome reports what Register did.
63	type Outcome struct {
64		Batch   Batch
65		Created bool // true when a record was added, false for an identical repeat
66	}
67	
68	// ConflictError reports that a batch id is already held by a different record.
69	// Fields lists every differing member among "product", "quantity" and "unit".
70	type ConflictError struct {
71		Batch  string
72		Fields []string
73	}
74	
75	func (e *ConflictError) Error() string {
76		return fmt.Sprintf("batch %q is already registered with conflicting field(s): %s; the existing record cannot be overwritten",
77			e.Batch, strings.Join(e.Fields, ", "))
78	}
79	
80	// DuplicateIDError reports two stored records sharing one batch id.
81	// First and Second are the 1-based positions of the two records in the
82	// batches array when known.
83	type DuplicateIDError struct {
84		Batch  string
85		First  int
86		Second int
87	}
88	
89	func (e *DuplicateIDError) Error() string {
90		if e.First > 0 && e.Second > 0 {
91			return fmt.Sprintf("registry contains multiple records for batch %q (records %d and %d)", e.Batch, e.First, e.Second)
92		}
93		return fmt.Sprintf("registry contains multiple records for batch %q", e.Batch)
94	}
95	
96	// FormatError reports a structural violation of the public registry file
97	// format: a missing, duplicated, misspelled, null or mistyped field, either
98	// in the root object (Position == 0) or in one batch record (Position is its
99	// 1-based index in "batches"). Batch carries the record's batch id only when
100	// it is uniquely determined; it stays empty when the "batch" member itself
101	// is missing, duplicated or not a string.
102	type FormatError struct {
103		Position int
104		Batch    string
105		Field    string
106		Reason   string
107	}
108	
109	func (e *FormatError) Error() string {
110		where := "root object"
111		if e.Position > 0 {
112			where = fmt.Sprintf("batches record %d", e.Position)
113			if e.Batch != "" {
114				where += fmt.Sprintf(" (batch %q)", e.Batch)
115			}
116		}
117		if e.Field != "" {
118			return fmt.Sprintf("%s: field %q: %s", where, e.Field, e.Reason)
119		}
120		return fmt.Sprintf("%s: %s", where, e.Reason)
121	}
122	
123	// NormalizeField trims leading and trailing whitespace; the result must stay
124	// non-empty. Interior characters, including interior whitespace, are kept,
125	// and casing is preserved so "B1" and "b1" are different values.
126	func NormalizeField(value string) (string, error) {
127		trimmed := strings.TrimSpace(value)
128		if trimmed == "" {
129			return "", errors.New("value must not be empty after trimming whitespace")
130		}
131		return trimmed, nil
132	}
133	
134	// ParseQuantity accepts a decimal positive integer made only of ASCII digits
135	// 0-9. Leading zeros are allowed; the numeric value is what gets stored and
136	// compared. Zero, signs, fractions, non-ASCII digits and values above the
137	// signed 64-bit maximum are rejected.
138	func ParseQuantity(text string) (int64, error) {
139		if !quantityPattern.MatchString(text) {
140			return 0, fmt.Errorf("quantity %q must be a positive decimal integer made only of digits 0-9", text)
141		}
142		value, err := strconv.ParseInt(text, 10, 64)
143		if err != nil {
144			return 0, fmt.Errorf("quantity %q must be a positive integer no greater than %d", text, MaxQuantity)
145		}
146		if value == 0 {
147			return 0, fmt.Errorf("quantity %q must be greater than zero", text)
148		}
149		return value, nil
150	}
151	
152	// Load reads the registry at path. A missing file yields an empty registry
153	// with existed == false. An existing file that is empty, not parseable as
154	// the public format — including missing, null, duplicated, misspelled or
155	// mistyped fields — of an unsupported version, or holding duplicate batch
156	// ids is an error: callers must never overwrite such a file as if it were a
157	// fresh registry.
158	func Load(path string) (reg *Registry, existed bool, err error) {
159		data, err := os.ReadFile(path)
160		if err != nil {
161			if errors.Is(err, fs.ErrNotExist) {
162				return &Registry{Version: FormatVersion}, false, nil
163			}
164			return nil, false, fmt.Errorf("cannot read registry %q: %w", path, err)
165		}
166		if len(bytes.TrimSpace(data)) == 0 {
167			return nil, true, fmt.Errorf("registry file %q is empty; refusing to replace it with a new registry", path)
168		}
169		reg, err = decode(data)
170		if err != nil {
171			return nil, true, fmt.Errorf("cannot parse registry %q as version %d JSON: %w", path, FormatVersion, err)
172		}
173		if err := validate(reg); err != nil {
174			return nil, true, fmt.Errorf("registry %q is not usable: %w", path, err)
175		}
176		return reg, true, nil
177	}
178	
179	// decode parses data as the public registry format. The root must be a JSON
180	// object holding exactly "version" (the integer 1) and "batches" (an array,
181	// possibly empty); every record must be an object holding exactly "batch",
182	// "product", "quantity" and "unit". Field names are matched case-sensitively
183	// after JSON string decoding, so "Version" or "Batch" are unknown fields and
184	// an escaped respelling such as "bat\u0063h" counts as the same field. A
185	// field appearing twice in one object is rejected even when both values are
186	// identical; missing fields, nulls, wrong types and unknown fields are
187	// rejected just the same. Nothing is patched up by taking the later value,
188	// merging or defaulting.
189	func decode(data []byte) (*Registry, error) {
190		dec := json.NewDecoder(bytes.NewReader(data))
191		var root json.RawMessage
192		if err := dec.Decode(&root); err != nil {
193			return nil, err
194		}
195		var extra json.RawMessage
196		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
197			if err == nil {
198				return nil, errors.New("unexpected data after registry object")
199			}
200			return nil, err
201		}
202	
203		fields, err := parseObjectFields(root)
204		if err != nil {
205			return nil, &FormatError{Reason: "root must be a JSON object holding exactly \"version\" and \"batches\""}
206		}
207		if dup, ok := duplicateField(fields); ok {
208			return nil, &FormatError{Field: dup, Reason: "field appears more than once; duplicate fields are not allowed"}
209		}
210		for _, f := range fields {
211			if f.key != "version" && f.key != "batches" {
212				return nil, &FormatError{Field: f.key, Reason: "unknown field; only \"version\" and \"batches\" are allowed"}
213			}
214		}
215		versionRaw, ok := findField(fields, "version")
216		if !ok {
217			return nil, &FormatError{Field: "version", Reason: "required field is missing"}
218		}
219		batchesRaw, ok := findField(fields, "batches")
220		if !ok {
221			return nil, &FormatError{Field: "batches", Reason: "required field is missing"}
222		}
223		version, err := parseRegistryVersion(versionRaw)
224		if err != nil {
225			return nil, err
226		}
227		if trimmed := bytes.TrimSpace(batchesRaw); len(trimmed) == 0 || trimmed[0] != '[' {
228			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
229		}
230		var elems []json.RawMessage
231		if err := json.Unmarshal(batchesRaw, &elems); err != nil {
232			return nil, &FormatError{Field: "batches", Reason: "must be an array of batch records"}
233		}
234		reg := &Registry{Version: version, Batches: make([]Batch, 0, len(elems))}
235		for i, raw := range elems {
236			b, err := parseRegistryRecord(raw, i+1)
237			if err != nil {
238				return nil, err
239			}
240			reg.Batches = append(reg.Batches, b)
241		}
242		return reg, nil
243	}
244	
245	// parseRegistryVersion accepts exactly the integer literal of FormatVersion.
246	// Other integers report an unsupported version; anything else (strings,
247	// fractions, exponents, booleans, null, arrays, objects) is a type error.
248	func parseRegistryVersion(raw json.RawMessage) (int, error) {
249		token := string(bytes.TrimSpace(raw))
250		if isJSONInteger(token) {
251			if token == strconv.Itoa(FormatVersion) {
252				return FormatVersion, nil
253			}
254			return 0, fmt.Errorf("unsupported registry version: got %s, want %d", token, FormatVersion)
255		}
256		return 0, &FormatError{Field: "version", Reason: fmt.Sprintf("must be the integer %d, not %s", FormatVersion, token)}
257	}
258	
259	// parseRegistryRecord validates one batches element: a JSON object with
260	// exactly the four required lowercase fields, text fields as JSON strings
261	// and quantity as a strict JSON integer in 1..MaxQuantity. pos is the
262	// record's 1-based position in the batches array.
263	func parseRegistryRecord(raw json.RawMessage, pos int) (Batch, error) {
264		var b Batch
265		fields, err := parseObjectFields(raw)
266		if err != nil {
267			return b, &FormatError{Position: pos, Reason: "record must be a JSON object holding exactly \"batch\", \"product\", \"quantity\" and \"unit\""}
268		}
269		// The batch id is attached to errors only when it is unambiguous:
270		// exactly one "batch" member carrying a JSON string. When the "batch"
271		// member itself is duplicated, no id is picked arbitrarily.
272		batchID := ""
273		if countField(fields, "batch") == 1 {
274			if rawID, _ := findField(fields, "batch"); rawID != nil {
275				var id string
276				if json.Unmarshal(rawID, &id) == nil {
277					batchID = id
278				}
279			}
280		}
281		fail := func(field, reason string) (Batch, error) {
282			return Batch{}, &FormatError{Position: pos, Batch: batchID, Field: field, Reason: reason}
283		}
284	
285		if dup, ok := duplicateField(fields); ok {
286			return fail(dup, "field appears more than once; duplicate fields are not allowed")
287		}
288		for _, f := range fields {
289			if _, ok := batchRecordFields[f.key]; !ok {
290				return fail(f.key, "unknown field; only \"batch\", \"product\", \"quantity\" and \"unit\" are allowed")
291			}
292		}
293	
294		text := func(name string) (string, error) {
295			rawValue, ok := findField(fields, name)
296			if !ok {
297				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "required field is missing"}
298			}
299			if trimmed := bytes.TrimSpace(rawValue); len(trimmed) == 0 || trimmed[0] != '"' {
300				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
301			}
302			var s string
303			if err := json.Unmarshal(rawValue, &s); err != nil {
304				return "", &FormatError{Position: pos, Batch: batchID, Field: name, Reason: "must be a JSON string"}
305			}
306			return s, nil
307		}
308		if b.Batch, err = text("batch"); err != nil {
309			return Batch{}, err
310		}
311		if b.Product, err = text("product"); err != nil {
312			return Batch{}, err
313		}
314		if b.Unit, err = text("unit"); err != nil {
315			return Batch{}, err
316		}
317		quantityRaw, ok := findField(fields, "quantity")
318		if !ok {
319			return fail("quantity", "required field is missing")
320		}
321		b.Quantity, err = parseRegistryQuantity(bytes.TrimSpace(quantityRaw))
322		if err != nil {
323			return fail("quantity", err.Error())
324		}
325		return b, nil
326	}
327	
328	// parseRegistryQuantity accepts exactly a strict JSON integer token in the
329	// range 1..MaxQuantity. Strings, signs, fractions, exponents, null and
330	// out-of-range values are rejected.
331	func parseRegistryQuantity(token []byte) (int64, error) {
332		if !isJSONInteger(string(token)) || len(token) == 0 || token[0] == '-' {
333			return 0, fmt.Errorf("must be a JSON integer between 1 and %d", MaxQuantity)
334		}
335		value, err := strconv.ParseInt(string(token), 10, 64)
336		if err != nil {
337			return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
338		}
339		if value == 0 {
340			return 0, errors.New("must be greater than zero")
341		}
342		return value, nil
343	}
344	
345	// isJSONInteger reports whether token is a JSON number literal without
346	// fraction or exponent. The token comes from validated JSON, so leading
347	// zeros cannot hide extra digits.
348	func isJSONInteger(token string) bool {
349		if token == "" {
350			return false
351		}
352		if token[0] == '-' {
353			token = token[1:]
354		}
355		if token == "" {
356			return false
357		}
358		for i := 0; i < len(token); i++ {
359			if token[i] < '0' || token[i] > '9' {
360				return false
361			}
362		}
363		return true
364	}
365	
366	// objectField is one member of a JSON object in source order; the key is
367	// the decoded JSON string, so escaped spellings compare by meaning.
368	type objectField struct {
369		key   string
370		value json.RawMessage
371	}
372	
373	// parseObjectFields decodes a single JSON object value into its members in
374	// source order, keeping duplicates visible for the caller to reject.
375	func parseObjectFields(raw []byte) ([]objectField, error) {
376		trimmed := bytes.TrimSpace(raw)
377		if len(trimmed) == 0 || trimmed[0] != '{' {
378			return nil, errors.New("value is not a JSON object")
379		}
380		dec := json.NewDecoder(bytes.NewReader(trimmed))
381		if _, err := dec.Token(); err != nil { // opening brace
382			return nil, err
383		}
384		var fields []objectField
385		for dec.More() {
386			tok, err := dec.Token()
387			if err != nil {
388				return nil, err
389			}
390			key, ok := tok.(string)
391			if !ok {
392				return nil, errors.New("object keys must be JSON strings")
393			}
394			var value json.RawMessage
395			if err := dec.Decode(&value); err != nil {
396				return nil, err
397			}
398			fields = append(fields, objectField{key: key, value: value})
399		}
400		if _, err := dec.Token(); err != nil { // closing brace
401			return nil, err
402		}
403		return fields, nil
404	}
405	
406	// duplicateField returns the first field name appearing more than once.
407	func duplicateField(fields []objectField) (string, bool) {
408		seen := make(map[string]struct{}, len(fields))
409		for _, f := range fields {
410			if _, dup := seen[f.key]; dup {
411				return f.key, true
412			}
413			seen[f.key] = struct{}{}
414		}
415		return "", false
416	}
417	
418	// findField returns the raw value of the first member named name.
419	func findField(fields []objectField, name string) (json.RawMessage, bool) {
420		for _, f := range fields {
421			if f.key == name {
422				return f.value, true
423			}
424		}
425		return nil, false
426	}
427	
428	// countField counts the members named name.
429	func countField(fields []objectField, name string) int {
430		n := 0
431		for _, f := range fields {
432			if f.key == name {
433				n++
434			}
435		}
436		return n
437	}
438	
439	func validate(reg *Registry) error {
440		seen := make(map[string]int, len(reg.Batches))
441		for i, b := range reg.Batches {
442			pos := i + 1
443			if b.Batch == "" || b.Product == "" || b.Unit == "" {
444				return fmt.Errorf("batches record %d (batch %q): batch, product and unit must all be non-empty", pos, b.Batch)
445			}
446			if b.Quantity <= 0 {
447				return fmt.Errorf("batches record %d (batch %q): quantity must be a positive integer", pos, b.Batch)
448			}
449			if first, dup := seen[b.Batch]; dup {
450				return &DuplicateIDError{Batch: b.Batch, First: first, Second: pos}
451			}
452			seen[b.Batch] = pos
453		}
454		return nil
455	}
456	
457	// ManifestRecordError reports a manifest record that is structurally invalid
458	// or carries a quantity outside the accepted range. Position is the record's
459	// 1-based position in the manifest.
460	type ManifestRecordError struct {
461		Position int
462		Batch    string // normalized batch id when available, otherwise ""
463		Reason   string
464	}
465	
466	func (e *ManifestRecordError) Error() string {
467		if e.Batch != "" {
468			return fmt.Sprintf("manifest record %d (batch %q): %s", e.Position, e.Batch, e.Reason)
469		}
470		return fmt.Sprintf("manifest record %d: %s", e.Position, e.Reason)
471	}
472	
473	// ManifestConflictError reports that a manifest record disagrees with the
474	// record already registered, or introduced earlier in the same manifest,
475	// under the same batch id. Position is the record's 1-based position in the
476	// manifest and Fields lists every differing member among "product",
477	// "quantity" and "unit" in that order.
478	type ManifestConflictError struct {
479		Position int
480		Batch    string
481		Fields   []string
482		Source   string // "registry" or "manifest"
483		PrevPos  int    // 1-based position of the earlier manifest record, if Source == "manifest"
484	}
485	
486	func (e *ManifestConflictError) Error() string {
487		if e.Source == "manifest" {
488			return fmt.Sprintf("manifest record %d (batch %q) conflicts with manifest record %d on field(s): %s; the whole manifest is rejected",
489				e.Position, e.Batch, e.PrevPos, strings.Join(e.Fields, ", "))
490		}
491		return fmt.Sprintf("manifest record %d (batch %q) conflicts with the registered record on field(s): %s; the whole manifest is rejected",
492			e.Position, e.Batch, strings.Join(e.Fields, ", "))
493	}
494	
495	// ParseManifest decodes data as a non-empty JSON array holding exactly the
496	// four required fields batch, product, quantity and unit per element. The
497	// three text fields must be JSON strings that are not blank after trimming;
498	// quantity must be a JSON integer (no strings, fractions or exponents) in
499	// the range 1..MaxQuantity. An empty file, empty array, non-array document
500	// or any malformed record is rejected. The manifest bytes are never written.
501	func ParseManifest(data []byte) ([]Input, error) {
502		trimmed := bytes.TrimSpace(data)
503		if len(trimmed) == 0 {
504			return nil, errors.New("manifest file is empty")
505		}
506		if trimmed[0] != '[' {
507			return nil, errors.New("manifest must be a non-empty JSON array of records")
508		}
509	
510		var elems []json.RawMessage
511		dec := json.NewDecoder(bytes.NewReader(data))
512		if err := dec.Decode(&elems); err != nil {
513			return nil, fmt.Errorf("manifest is not valid JSON: %w", err)
514		}
515		var extra json.RawMessage
516		if err := dec.Decode(&extra); !errors.Is(err, io.EOF) {
517			if err == nil {
518				return nil, errors.New("manifest has unexpected data after the array")
519			}
520			return nil, fmt.Errorf("manifest must be a single JSON array: %w", err)
521		}
522		if len(elems) == 0 {
523			return nil, errors.New("manifest must contain at least one record")
524		}
525	
526		inputs := make([]Input, 0, len(elems))
527		for i, raw := range elems {
528			pos := i + 1
529			in, err := parseManifestRecord(raw)
530			if err != nil {
531				return nil, &ManifestRecordError{Position: pos, Batch: in.Batch, Reason: err.Error()}
532			}
533			inputs = append(inputs, in)
534		}
535		return inputs, nil
536	}
537	
538	// batchRecordFields are the only members a batch record may carry, in the
539	// registry file and in an import manifest alike.
540	var batchRecordFields = map[string]struct{}{
541		"batch": {}, "product": {}, "quantity": {}, "unit": {},
542	}
543	
544	// parseManifestRecord validates one manifest element: it must be a JSON
545	// object with exactly the four required keys, text fields as non-blank
546	// strings and quantity as a strict JSON integer.
547	func parseManifestRecord(raw json.RawMessage) (Input, error) {
548		var in Input
549		if len(bytes.TrimSpace(raw)) == 0 || bytes.TrimSpace(raw)[0] != '{' {
550			return in, errors.New("record must be a JSON object with batch, product, quantity and unit")
551		}
552		fields := make(map[string]json.RawMessage)
553		if err := json.Unmarshal(raw, &fields); err != nil {
554			return in, fmt.Errorf("record is not valid JSON: %w", err)
555		}
556		for name := range fields {
557			if _, ok := batchRecordFields[name]; !ok {
558				return in, fmt.Errorf("record has unknown field %q; only batch, product, quantity and unit are allowed", name)
559			}
560		}
561		keys, err := objectKeys(raw)
562		if err != nil {
563			return in, err
564		}
565		counts := make(map[string]int, len(keys))
566		for _, k := range keys {
567			counts[k]++
568			if counts[k] > 1 {
569				return in, fmt.Errorf("record lists field %q more than once", k)
570			}
571		}
572	
573		textField := func(name string) (string, error) {
574			value, ok := fields[name]
575			if !ok {
576				return "", fmt.Errorf("missing required field %q", name)
577			}
578			var text string
579			if err := json.Unmarshal(value, &text); err != nil {
580				return "", fmt.Errorf("field %q must be a JSON string", name)
581			}
582			normalized, err := NormalizeField(text)
583			if err != nil {
584				return "", fmt.Errorf("field %q must not be blank: %w", name, err)
585			}
586			return normalized, nil
587		}
588	
589		in.Batch, err = textField("batch")
590		if err != nil {
591			return in, err
592		}
593		in.Product, err = textField("product")
594		if err != nil {
595			return in, err
596		}
597		in.Unit, err = textField("unit")
598		if err != nil {
599			return in, err
600		}
601		quantityRaw, ok := fields["quantity"]
602		if !ok {
603			return in, errors.New("missing required field \"quantity\"")
604		}
605		in.Quantity, err = parseManifestQuantity(bytes.TrimSpace(quantityRaw))
606		if err != nil {
607			return in, err
608		}
609		return in, nil
610	}
611	
612	// objectKeys returns the member keys of a JSON object in source order,
613	// flagging repeated names for the caller.
614	func objectKeys(raw json.RawMessage) ([]string, error) {
615		fields, err := parseObjectFields(raw)
616		if err != nil {
617			return nil, err
618		}
619		keys := make([]string, len(fields))
620		for i, f := range fields {
621			keys[i] = f.key
622		}
623		return keys, nil
624	}
625	
626	// parseManifestQuantity accepts exactly a strict JSON integer token in the
627	// range 1..MaxQuantity. Strings, signs, fractions, exponents, leading zeros
628	// and out-of-range values are rejected instead of silently rounded.
629	func parseManifestQuantity(token []byte) (int64, error) {
630		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
631			return 0, fmt.Errorf("field %q must be a JSON integer between 1 and %d", "quantity", MaxQuantity)
632		}
633		for _, c := range token {
634			if c < '0' || c > '9' {
635				return 0, fmt.Errorf("field %q must be a JSON integer without sign, fraction or exponent", "quantity")
636			}
637		}
638		if len(token) > 1 && token[0] == '0' {
639			return 0, errors.New("field \"quantity\" must be a JSON integer without leading zeros")
640		}
641		value, err := strconv.ParseInt(string(token), 10, 64)
642		if err != nil {
643			return 0, fmt.Errorf("field %q must be an integer no greater than %d", "quantity", MaxQuantity)
644		}
645		if value == 0 {
646			return 0, errors.New("field \"quantity\" must be greater than zero")
647		}
648		return value, nil
649	}
650	
651	// ImportResult is one entry of an Import outcome: the normalized record in
652	// manifest order plus whether it was newly created or already present.
653	type ImportResult struct {
654		Batch   Batch
655		Created bool
656	}
657	
658	// Import validates every record of inputs before appending anything: the
659	// whole manifest fails if any record conflicts with a stored record or with
660	// an earlier manifest record, and reg is left untouched on error. New batch
661	// ids are appended in first-occurrence order; an id already stored or
662	// introduced earlier in the same manifest is confirmed as a duplicate only
663	// when product, quantity and unit all match. Results come back in manifest
664	// order; Created is false for duplicates.
665	func Import(reg *Registry, inputs []Input) (results []ImportResult, err error) {
666		if reg.Version != FormatVersion {
667			return nil, fmt.Errorf("unsupported registry version %d", reg.Version)
668		}
669		if len(inputs) == 0 {
670			return nil, errors.New("manifest must contain at least one record")
671		}
672	
673		// Work on a copy: a rejected manifest must never partially land in reg.
674		working := append([]Batch(nil), reg.Batches...)
675		indexByID := make(map[string]int, len(working))
676		for i, b := range working {
677			indexByID[b.Batch] = i
678		}
679		firstPos := make(map[string]int, len(inputs)) // manifest 1-based position of a newly introduced id
680	
681		out := make([]ImportResult, len(inputs))
682		for i, in := range inputs {
683			pos := i + 1
684			if idx, known := indexByID[in.Batch]; known {
685				existing := working[idx]
686				diffs := diffFields(existing, in)
687				if len(diffs) > 0 {
688					if prev, inManifest := firstPos[in.Batch]; inManifest {
689						return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "manifest", PrevPos: prev}
690					}
691					return nil, &ManifestConflictError{Position: pos, Batch: in.Batch, Fields: diffs, Source: "registry"}
692				}
693				out[i] = ImportResult{Batch: existing, Created: false}
694				continue
695			}
696			b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
697			working = append(working, b)
698			indexByID[in.Batch] = len(working) - 1
699			firstPos[in.Batch] = pos
700			out[i] = ImportResult{Batch: b, Created: true}
701		}
702	
703		reg.Batches = working
704		return out, nil
705	}
706	
707	// diffFields lists the members of product, quantity and unit in which in
708	// differs from existing, in that fixed order.
709	func diffFields(existing Batch, in Input) []string {
710		var diffs []string
711		if existing.Product != in.Product {
712			diffs = append(diffs, "product")
713		}
714		if existing.Quantity != in.Quantity {
715			diffs = append(diffs, "quantity")
716		}
717		if existing.Unit != in.Unit {
718			diffs = append(diffs, "unit")
719		}
720		return diffs
721	}
722	
723	// Register adds in to reg, or confirms the identical record already stored
724	// under the same batch id. A batch id held by a record differing in product,
725	// quantity or unit produces a *ConflictError and leaves reg untouched. The
726	// zero Outcome is returned together with the error.
727	func Register(reg *Registry, in Input) (Outcome, error) {
728		if reg.Version != FormatVersion {
729			return Outcome{}, fmt.Errorf("unsupported registry version %d", reg.Version)
730		}
731		if in.Batch == "" || in.Product == "" || in.Unit == "" {
732			return Outcome{}, errors.New("batch, product and unit must be non-empty")
733		}
734		if in.Quantity <= 0 || in.Quantity > MaxQuantity {
735			return Outcome{}, fmt.Errorf("quantity must be a positive integer no greater than %d", MaxQuantity)
736		}
737		for _, b := range reg.Batches {
738			if b.Batch != in.Batch {
739				continue
740			}
741			var diffs []string
742			if b.Product != in.Product {
743				diffs = append(diffs, "product")
744			}
745			if b.Quantity != in.Quantity {
746				diffs = append(diffs, "quantity")
747			}
748			if b.Unit != in.Unit {
749				diffs = append(diffs, "unit")
750			}
751			if len(diffs) > 0 {
752				return Outcome{}, &ConflictError{Batch: in.Batch, Fields: diffs}
753			}
754			return Outcome{Batch: b, Created: false}, nil
755		}
756		b := Batch{Batch: in.Batch, Product: in.Product, Quantity: in.Quantity, Unit: in.Unit}
757		reg.Batches = append(reg.Batches, b)
758		return Outcome{Batch: b, Created: true}, nil
759	}
760	
761	// Save atomically writes reg to path, replacing the file only after the new
762	// content is fully on disk so an existing registry stays usable on failure.
763	// Records are serialized in their current order; the file is created with
764	// 0644 permissions or, when replacing an existing file, with its permissions.
765	func Save(path string, reg *Registry) error {
766		if reg.Version != FormatVersion {
767			return fmt.Errorf("cannot write registry format version %d", reg.Version)
768		}
769		mode := os.FileMode(0o644)
770		if info, err := os.Stat(path); err == nil {
771			mode = info.Mode().Perm()
772		} else if !errors.Is(err, fs.ErrNotExist) {
773			return fmt.Errorf("cannot inspect registry %q: %w", path, err)
774		}
775	
776		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
777			return fmt.Errorf("cannot save registry %q: %w", path, err)
778		}
779	
780		var buf bytes.Buffer
781		enc := json.NewEncoder(&buf)
782		enc.SetEscapeHTML(false)
783		enc.SetIndent("", "  ")
784		if err := enc.Encode(reg); err != nil {
785			return fmt.Errorf("cannot encode registry %q: %w", path, err)
786		}
787	
788		tmp, err := os.CreateTemp(filepath.Dir(path), ".govflow-registry-*.tmp")
789		if err != nil {
790			return fmt.Errorf("cannot save registry %q: %w", path, err)
791		}
792		tmpName := tmp.Name()
793		abort := func(cause error) error {
794			tmp.Close()
795			os.Remove(tmpName)
796			return fmt.Errorf("cannot save registry %q: %w", path, cause)
797		}
798		if _, err := tmp.Write(buf.Bytes()); err != nil {
799			return abort(err)
800		}
801		if err := tmp.Chmod(mode); err != nil {
802			return abort(err)
803		}
804		if err := tmp.Sync(); err != nil {
805			return abort(err)
806		}
807		if err := tmp.Close(); err != nil {
808			os.Remove(tmpName)
809			return fmt.Errorf("cannot save registry %q: %w", path, err)
810		}
811		if err := os.Rename(tmpName, path); err != nil {
812			os.Remove(tmpName)
813			return fmt.Errorf("cannot save registry %q: %w", path, err)
814		}
815		return nil
816	}
817

