15			in    string
16			want  string
17			valid bool
18		}{
19			{"plain", "B-001", "B-001", true},
20			{"trims ends", "\t B-001 \n", "B-001", true},
21			{"keeps interior", "B 001", "B 001", true},
22			{"keeps case", "b1", "b1", true},
23			{"empty", "", "", false},
24			{"only whitespace", " \t\n", "", false},
25		}
26		for _, tc := range cases {
27			t.Run(tc.name, func(t *testing.T) {
28				got, err := NormalizeField(tc.in)
29				if tc.valid {
30					if err != nil {
31						t.Fatalf("unexpected error: %v", err)
32					}
33					if got != tc.want {
34						t.Fatalf("got %q, want %q", got, tc.want)
35					}
36				} else if err == nil {
37					t.Fatalf("expected error for %q, got %q", tc.in, got)
38				}
39			})
40		}
41	}
42	
43	func TestParseQuantity(t *testing.T) {
44		const max = "9223372036854775807"
45		valid := map[string]int64{
46			"1":                   1,
47			"0007":                7,
48			"120":                 120,
49			max:                   MaxQuantity,
50			"0000000000000000001": 1,
51		}
52		for in, want := range valid {
53			got, err := ParseQuantity(in)
54			if err != nil {
55				t.Fatalf("ParseQuantity(%q) unexpected error: %v", in, err)
56			}
57			if got != want {
58				t.Fatalf("ParseQuantity(%q) = %d, want %d", in, got, want)
59			}
60		}
61		invalid := []string{
62			"0", "0000", "-1", "+1", "1.0", "1e3", " 1", "1 ",
63			"abc", "１２", "9223372036854775808", "99999999999999999999999", "",
64		}
65		for _, in := range invalid {
66			if _, err := ParseQuantity(in); err == nil {
67				t.Fatalf("ParseQuantity(%q) expected error", in)
68			}
69		}
70	}
71	
72	func writeRegistry(t *testing.T, path, content string) {
73		t.Helper()
74		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
75			t.Fatal(err)
76		}
77		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
78			t.Fatal(err)
79		}
80	}
81	
82	func TestRegisterCreatesAndPersists(t *testing.T) {
83		path := filepath.Join(t.TempDir(), "nested", "registry.json")
84	
85		reg, existed, err := Load(path)
86		if err != nil {
87			t.Fatal(err)
88		}
89		if existed {
90			t.Fatal("registry should not exist yet")
91		}
92		out, err := Register(reg, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
93		if err != nil {
94			t.Fatal(err)
95		}
96		if !out.Created || out.Batch.Quantity != 120 {
97			t.Fatalf("unexpected outcome: %+v", out)
98		}
99		if err := Save(path, reg); err != nil {
100			t.Fatal(err)
101		}
102	
103		// Restart: old batch must still be recognized.
104		reg2, existed, err := Load(path)
105		if err != nil || !existed {
106			t.Fatalf("reload: existed=%v err=%v", existed, err)
107		}
108		out, err = Register(reg2, Input{Batch: "B-1", Product: "P-7", Quantity: 120, Unit: "kg"})
109		if err != nil {
110			t.Fatal(err)
111		}
112		if out.Created {
113			t.Fatal("identical repeat should be a duplicate, not a create")
114		}
115	
