	bad := []byte("{\"batch\":\"B\xff\xfe\",\"product\":\"P\",\"quantity\":1,\"unit\":\"kg\"}")
	var m map[string]json.RawMessage
	err := json.Unmarshal(bad, &m)
	fmt.Printf("unmarshal map err: %v\n", err)
	if raw, ok := m["batch"]; ok {
		var s string
		e2 := json.Unmarshal(raw, &s)
		fmt.Printf("batch raw=% x -> string %q err=%v\n", []byte(raw), s, e2)
	}

	// 2. decoder token over object with invalid key
	dec := json.NewDecoder(bytes.NewReader(bad))
	for {
		tok, e := dec.Token()
		if e != nil {
			fmt.Printf("token end err: %v\n", e)
			break
		}
		fmt.Printf("token: %#v (%T)\n", tok, tok)
	}

	// 3. lone surrogate escape
	sur := []byte(`{"batch":"B\ud800","product":"P"}`)
	dec2 := json.NewDecoder(bytes.NewReader(sur))
	var root json.RawMessage
	fmt.Printf("decode raw err: %v\n", dec2.Decode(&root))
	var s string
	fmt.Printf("surrogate unmarshal: %q err=%v\n", mustUnmarshal(root), json.Unmarshal([]byte(`"B\ud800"`), &s))
	fmt.Printf("s = %q (bytes % x)\n", s, []byte(s))

	// 4. valid replacement char
	var s2 string
	fmt.Printf("real FFFD: err=%v q=%q\n", json.Unmarshal([]byte(`"B�"`), &s2), s2)

	// 5. extra data after
	dec3 := json.NewDecoder(bytes.NewReader(append(append([]byte{}, bad...), ' ', 'x')))
	var extra json.RawMessage
	e3 := dec3.Decode(&root)
	fmt.Printf("bad doc decode err: %v\n", e3)
	e4 := dec3.Decode(&extra)
	fmt.Printf("second decode: err=%v isEOF=%v\n", e4, e4 == io.EOF)
}

func mustUnmarshal(r json.RawMessage) string {
	var m map[string]string
	_ = json.Unmarshal(r, &m)
	return m["batch"]
}
