// bytes of a CLI argument, or a JSON string value whose source bytes hold
// malformed UTF-8 or a lone surrogate escape. The stored/parsed value must
// never be pointed at, since decoding it would substitute U+FFFD and make
// distinct inputs collide. Field is one of "batch", "product" and "unit";
// Position is the 1-based record position (0 for a single CLI value).
type EncodingError struct {
	Field    string
	Position int
}

func (e *EncodingError) Error() string {
	if e.Position > 0 {
		return fmt.Sprintf("field %q of record %d contains bytes that are not valid UTF-8; the value is rejected instead of being replaced", e.Field, e.Position)
	}
	return fmt.Sprintf("field %q contains bytes that are not valid UTF-8; the value is rejected instead of being replaced", e.Field)
}

