package main

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
	"unicode/utf8"
)

// copy of the implementation under test
func strict(raw []byte) (string, error) {
	token := bytes.TrimSpace(raw)
	if len(token) < 2 || token[0] != '"' || token[len(token)-1] != '"' {
		return "", errNJ
	}
	var b strings.Builder
	i := 1
	for i < len(token)-1 {
		c := token[i]
		switch {
		case c == '"':
			return "", errNJ
		case c == '\\':
			if i+1 >= len(token)-1 {
				return "", errNJ
			}
			switch token[i+1] {
			case '"', '\\', '/':
				b.WriteByte(token[i+1])
				i += 2
			case 'b':
				b.WriteByte('\b')
				i += 2
			case 'f':
				b.WriteByte('\f')
				i += 2
			case 'n':
				b.WriteByte('\n')
				i += 2
			case 'r':
				b.WriteByte('\r')
				i += 2
			case 't':
				b.WriteByte('\t')
				i += 2
			case 'u':
				r, size, err := decU(token[i:])
				if err != nil {
					return "", err
				}
				b.WriteRune(r)
				i += size
			default:
				return "", errNJ
			}
		case c < 0x20:
			return "", errNJ
		default:
			r, size := utf8.DecodeRune(token[i : len(token)-1])
			if r == utf8.RuneError && size == 1 {
				return "", errEnc
			}
			b.WriteRune(r)
			i += size
		}
	}
	if i != len(token)-1 {
		return "", errNJ
	}
	return b.String(), nil
}

var errNJ = errx("not json")
var errEnc = errx("encoding")

type errx string

func (e errx) Error() string { return string(e) }

func decU(p []byte) (rune, int, error) {
	hi, ok := hex4(p)
	if !ok {
		return 0, 0, errNJ
	}
	switch {
	case hi >= 0xD800 && hi <= 0xDBFF:
		if len(p) < 12 || p[6] != '\\' || p[7] != 'u' {
			return 0, 0, errEnc
		}
		lo, ok := hex4(p[6:])
		if !ok {
			return 0, 0, errNJ
		}
		if lo < 0xDC00 || lo > 0xDFFF {
			return 0, 0, errEnc
		}
		return 0x10000 + (rune(hi)-0xD800)<<10 + (rune(lo) - 0xDC00), 12, nil
	case hi >= 0xDC00 && hi <= 0xDFFF:
		return 0, 0, errEnc
	default:
		return rune(hi), 6, nil
	}
}

func hex4(p []byte) (int, bool) {
	if len(p) < 6 || p[0] != '\\' || p[1] != 'u' {
		return 0, false
	}
	v := 0
	for _, c := range p[2:6] {
		var d byte
		switch {
		case c >= '0' && c <= '9':
			d = c - '0'
		case c >= 'a' && c <= 'f':
			d = c - 'a' + 10
		case c >= 'A' && c <= 'F':
			d = c - 'A' + 10
		default:
			return 0, false
		}
		v = v<<4 | int(d)
	}
	return v, true
}

// classification oracle: lenient decoder succeeds AND result is valid utf8
// => strict must succeed with same value; otherwise strict must fail.
func FuzzCompare(f *testing.F) {
	seeds := []string{
		`"abc"`, `""`, `"é"`, `"😀"`, `"中"`, `"�"`, `"\n\t\""`,
		"\"\xff\"", "\"\xc0\x80\"", "\"\xe4\xb8\"", `"\ud800"`, `"\udc00"`,
		`"😀"`, `"é"`, `"�"`, `"\u"`, `"\x"`, "\"a\tb\"",
		`"\uD83D"`, `"\ud83dA"`, `"a"x`, `"abc`,
