	f.Fuzz(func(t *testing.T, s string) {
		raw := []byte(s)
		var lenient string
		lerr := json.Unmarshal(raw, &lenient)
		got, gerr := strict(raw)
		lenientOK := lerr == nil && utf8.ValidString(lenient)
		strictOK := gerr == nil
		if lenientOK != strictOK {
			t.Fatalf("classify mismatch for % x: lenient=%q(%v) strict=%q(%v)", raw, lenient, lerr, got, gerr)
		}
		if lenientOK && got != lenient {
			t.Fatalf("value mismatch for % x: %q vs %q", raw, got, lenient)
		}
	})
}
