		`"😀"`:           "😀",
		`"a�b"`:         "a�b",            // genuine U+FFFD written directly
		`"�"`:      "�",             // genuine U+FFFD written as an escape
		`"B-001"`:  "B-001",         // escape means the same character
		`"😀"`: "😀",            // matched surrogate pair
		`"\n\t\"\\"`:   "\n\t\"\\",       // simple escapes
		"  \"x\"\r\n":   "x",             // JSON whitespace around the token
	}
	for raw, want := range valid {
		got, err := unmarshalStringStrict([]byte(raw))
		if err != nil {
			t.Errorf("unmarshalStringStrict(%s) unexpected error: %v", raw, err)
			continue
		}
		if got != want {
			t.Errorf("unmarshalStringStrict(%s) = %q, want %q", raw, got, want)
		}
	}

