func badUTF8(parts ...string) string {
	// Joins parts with a 0xFF byte between them: a handy invalid value.
	return strings.Join(parts, "\xff")
}

// batch-register must refuse malformed UTF-8 in any text flag, naming the
// offending flag, before creating or touching the registry.
func TestBatchRegisterRejectsBadUTF8Flags(t *testing.T) {
	cases := []struct {
		name string
		flag string
	}{
		{"batch", "--batch"},
		{"product", "--product"},
		{"unit", "--unit"},
		{"batch with surrounding whitespace", "--batch"},
	}
	values := map[string]string{
		"--batch":                                badUTF8(" B", " "),
		"--product":                              badUTF8("P"),
		"--unit":                                 badUTF8(" kg", ""),
		"batch with surrounding whitespace":      " B\xff ",
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dir := t.TempDir()
			registry := filepath.Join(dir, "reg.json")
			args := []string{
				"--registry", registry,
				"--batch", "B1", "--product", "P",
				"--quantity", "1", "--unit", "kg",
			}
			val := values[tc.flag]
			if tc.name == "batch with surrounding whitespace" {
				val = values[tc.name]
			}
			args = append(args[:0],
				"--registry", registry,
				"--batch", flagOr(tc.flag, val, "--batch", "B1"),
				"--product", flagOr(tc.flag, val, "--product", "P"),
				"--quantity", "1",
				"--unit", flagOr(tc.flag, val, "--unit", "kg"),
			)
