			if tc.name == "batch with surrounding whitespace" {
				val = values[tc.name]
			}
			args = append(args[:0],
				"--registry", registry,
				"--batch", flagOr(tc.flag, val, "--batch", "B1"),
				"--product", flagOr(tc.flag, val, "--product", "P"),
				"--quantity", "1",
				"--unit", flagOr(tc.flag, val, "--unit", "kg"),
			)
			var stdout bytes.Buffer
			err := runBatchRegister(args, &stdout)
			if err == nil {
				t.Fatal("malformed UTF-8 must be rejected")
			}
			if !strings.Contains(err.Error(), tc.flag) {
				t.Fatalf("error must name %q: %v", tc.flag, err)
			}
			if !strings.Contains(err.Error(), "UTF-8") {
				t.Fatalf("error must explain the encoding problem: %v", err)
			}
			if stdout.Len() != 0 {
				t.Fatalf("stdout must stay empty: %q", stdout.String())
			}
			if _, statErr := os.Stat(registry); !os.IsNotExist(statErr) {
				t.Fatal("a rejected registration must not create the registry file")
			}
		})
	}
}

// flagOr returns val when flag matches current, otherwise fallback.
func flagOr(current, val, flag, fallback string) string {
	if current == flag {
		return val
	}
	return fallback
}

